import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import { BrowserRouter, Routes, Route } from 'react-router-dom'
import './index.css'
import i18n, { resources, LANGUAGE_STORAGE_KEY, supportedLanguages } from './i18n/config'
import { initReactI18next } from 'react-i18next'
import App from './App.jsx'

// Check if we were redirected from 404.html (GitHub Pages)
const redirectPath = sessionStorage.getItem('redirectPath');
const actualPath = redirectPath || window.location.pathname;

// Detect language from the actual path (not the redirected one)
const pathMatch = actualPath.match(/^\/([a-z]{2})(\/|$)/);
let urlLang = null;
let detectedLang = 'en';

if (pathMatch && supportedLanguages.includes(pathMatch[1])) {
  urlLang = pathMatch[1];
}

// Check localStorage first
let hasStoredPreference = false;
try {
  const stored = localStorage.getItem(LANGUAGE_STORAGE_KEY);
  if (stored && supportedLanguages.includes(stored)) {
    detectedLang = stored;
    hasStoredPreference = true;
  }
} catch {
  // localStorage not available (incognito mode, etc.)
}

// Browser language detection (only if no stored preference)
if (!hasStoredPreference) {
  const browserLang = navigator.language || navigator.userLanguage;
  if (browserLang) {
    const langCode = browserLang.toLowerCase().split('-')[0];
    if (supportedLanguages.includes(langCode)) {
      detectedLang = langCode;
      console.log('Detected browser language:', detectedLang);
    }
  }
}

// If no URL language but detected is not English, redirect
if (!urlLang && detectedLang !== 'en') {
  let newPath;
  const pathWithoutLang = actualPath.replace(/^\/[a-z]{2}(\/|$)/, '/');

  if (detectedLang === 'en') {
    newPath = pathWithoutLang === '' ? '/' : pathWithoutLang;
  } else {
    if (pathWithoutLang === '/') {
      newPath = `/${detectedLang}`;
    } else {
      newPath = `/${detectedLang}${pathWithoutLang}`;
    }
  }

  // Redirect to correct language
  console.log('Redirecting from', actualPath, 'to', newPath);
  window.location.href = newPath + window.location.search + window.location.hash;
}

// If we were redirected, update the URL back to the intended path
if (redirectPath) {
  window.history.replaceState(null, '', redirectPath);
  sessionStorage.removeItem('redirectPath');
}

// Initialize i18n synchronously with the appropriate language BEFORE rendering
i18n
  .use(initReactI18next)
  .init({
    resources,
    lng: urlLang || detectedLang,
    fallbackLng: 'en',
    supportedLngs: supportedLanguages,
    interpolation: {
      escapeValue: false
    },
    react: {
      useSuspense: false
    }
  });

// Only use StrictMode in development - it causes double renders which slow down initial load
const AppWrapper = import.meta.env.DEV ? (
  <StrictMode>
    <BrowserRouter>
      <Routes>
        <Route path="/:lang?" element={<App />} />
      </Routes>
    </BrowserRouter>
  </StrictMode>
) : (
  <BrowserRouter>
    <Routes>
      <Route path="/:lang?" element={<App />} />
    </Routes>
  </BrowserRouter>
);

createRoot(document.getElementById('root')).render(AppWrapper);
